/* * @lc app=leetcode id=1032 lang=kotlin * * [1032] Stream of Characters */ class StreamChecker(words: Array<String>) : HashMap<String, Any?>() { init { put("t", Array(400005) { IntArray(27) }).also { put("n", intArrayOf(1)) }.also { put("s", CharArray(40005)) }.also { put("i", intArrayOf(0)) }.also { intArrayOf(0, 0, 0, 0).apply { while (this[0] < words.size) { this.apply { this[1] = words[this[0]].length - 1 }.apply { this[2] = 0 }.apply { while (this[1] >= 0) { this.apply { this[3] = words[this[0]][this[1]] - 'a' }.apply { if ((get("t") as Array<IntArray>)[this[2]][this[3]] == 0) (get("t") as Array<IntArray>)[this[2]][this[3]] = (get("n") as IntArray)[0]++ }.apply { this[2] = (get("t") as Array<IntArray>)[this[2]][this[3]] }.apply { this[1] -= 1 } } }.apply { (get("t") as Array<IntArray>)[this[2]][26] = 1 }.apply { this[0] += 1 } } } } } fun query(letter: Char): Boolean = intArrayOf(0, (get("i") as IntArray)[0], 0, 0).apply { (get("s") as CharArray)[(get("i") as IntArray)[0]++] = letter }.apply { while (this[1] >= Math.max(0, (get("i") as IntArray)[0] - 2005) && this[2] != -1) { this.apply { this[3] = (get("s") as CharArray)[this[1]] - 'a' }.apply { if ((get("t") as Array<IntArray>)[this[2]][this[3]] == 0) this.apply { this[2] = -1 } else this.apply { this[2] = (get("t") as Array<IntArray>)[this[2]][this[3]] }.apply { if ((get("t") as Array<IntArray>)[this[2]][26] == 1) this.apply { this[0] = 1 }.apply { this[2] = -1 } else this.apply { this[1] -= 1 } } } } }.let { put("ans", it[0] == 1) }.let { get("ans") == true } }